<script lang="ts">import { onMount } from 'svelte'; import { api } from '$lib/api'; import type { Student, Guardian, Program, Content } from '$lib/types'; let students: Student[]=[]; let guardians: Guardian[]=[]; let programs: Program[]=[]; let announcements: Content[]=[]; let error=''; onMount(async()=>{try{[students,guardians,programs,announcements]=await Promise.all([api<Student[]>('/api/students'),api<Guardian[]>('/api/guardians'),api<Program[]>('/api/programs'),api<Content[]>('/api/announcements')]);}catch(e){error=e instanceof Error?e.message:'Could not load dashboard.';}});</script>
<svelte:head><title>Staff dashboard | TASK Karate</title></svelte:head><div class="toolbar"><div><span class="eyebrow">TODAY</span><h2>Good work starts with a clear desk.</h2></div></div>{#if error}<div class="error">{error}</div>{/if}<div class="metric-grid"><section class="card metric"><strong>{students.length}</strong><span>Active students</span></section><section class="card metric"><strong>{guardians.length}</strong><span>Active guardians</span></section><section class="card metric"><strong>{programs.length}</strong><span>Programs</span></section><section class="card metric"><strong>{announcements.filter(x=>x.status==='Published').length}</strong><span>Published announcements</span></section></div><section class="card"><span class="eyebrow">WORKFLOWS</span><h2>What needs attention?</h2><div class="schedule-grid"><a class="schedule-item" href="/staff/students"><b>Manage students</b><small>Create, edit, view, or deactivate student records.</small></a><a class="schedule-item" href="/staff/classes"><b>Prepare today’s classes</b><small>Create sessions from your class templates.</small></a><a class="schedule-item" href="/staff/attendance"><b>Check attendance</b><small>Record a student once per session.</small></a><a class="schedule-item" href="/staff/announcements"><b>Publish an announcement</b><small>Drafts stay private until published.</small></a></div></section>
